; Block: p8b_txt

p8b_txt:

; ---- Subroutine: p8b_txt.p8s_chrout ----
    ALIGN 2

p8b_txt.p8s_chrout:
            move.l  sys.DOSBase,a6
            move.b  d0,-(sp)          ; 1. Push character onto the stack. A7 now points to it!
            move.l  4.w,a0
            cmp.w   #36,20(a0)      ; KS 2.0 = V36
            bcc.s   .use_writechars

            jsr     -60(a6)           ; Output()
            move.l  d0, d1
            move.l  sp, d2             ; D2 = Pointer to our character (Current Stack Pointer)
            moveq   #1, d3             ; D3 = We only want to write exactly 1 byte
            jsr     -48(a6)           ; Write()
            addq.l  #2, sp
            rts

.use_writechars:
            move.l  sp, d1
            moveq   #1, d2
            jsr     -942(a6)        ; WriteChars (ks 2.0+)
            addq.l  #2, sp
            rts
; End of subroutine: p8b_txt.p8s_chrout


; ---- Subroutine: p8b_txt.p8s_flush ----
    ALIGN 2

p8b_txt.p8s_flush:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcc.s   .do_flush
            rts
.do_flush:
            move.l  sys.DOSBase,a6
            jsr     -60(a6)
            move.l  d0,d1
            jmp     -360(a6)       ; Flush (ks 2.0+)
; End of subroutine: p8b_txt.p8s_flush


; ---- Subroutine: p8b_txt.p8s_print ----
    ALIGN 2

p8b_txt.p8s_print:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcc.s   .use_putstr
            move.l  a0,d2
            jsr  strings.length
            move.l  d0,d3
            move.l  sys.DOSBase,a6
            jsr     -60(a6)           ; Output()
            move.l  d0,d1
            jmp     -48(a6)           ; Write()
.use_putstr:
            move.l  sys.DOSBase,a6
            move.l  a0,d1
            jsr     -948(a6)          ; PutStr()  (KS 2.0+)
            jsr     -60(a6)         ; Output()
            move.l  d0,d1
            jmp     -360(a6)       ; Flush (ks 2.0+)
; End of subroutine: p8b_txt.p8s_print


; ---- Subroutine: p8b_txt.p8s_vprintf ----
    ALIGN 2

p8b_txt.p8s_vprintf:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcs.s   .no_ks20
            move.l  sys.DOSBase,a6
            jmp  dos.VPrintf(a6)

.no_ks20:
            jmp  p8b_txt.p8s_no_ks20_alert
; End of subroutine: p8b_txt.p8s_vprintf


; ---- Subroutine: p8b_txt.p8s_no_ks20_alert ----
    ALIGN 2

p8b_txt.p8s_no_ks20_alert:
            move.l  #$00070001,d0
            lea     _msg(pc),a0
            moveq   #40,d1
            move.l  sys.IntuitionBase,a6
            jsr     -90(a6)                 ; DisplayAlert
            moveq   #1,d0
            jmp     sys.exit

            even
_msg:
            dc.w    20
            dc.b    16
            dc.b    "textio/conv number format routines require Kickstart 2.0+",0
            dc.b    0
            ; !notreached!
; End of subroutine: p8b_txt.p8s_no_ks20_alert

