            movea.l  d0,a0
            move.b   #179,d0
            moveq    #0,d1
            move.w   d1,ccr          ; clear flags (X=0 for roxl)
            bra      .enter
.loop:
            roxl.b   #1,d0
            eor.b    d1,d0
.enter:
            move.b   (a0)+,d1
            bne      .loop
            rts
; End of subroutine: strings.hash


; ---- Subroutine: strings.copy ----
    ALIGN 2

strings.copy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
.loop:
            move.b   (a0)+,d2
            move.b   d2,(a1)+
            beq      .done
            addq.l   #1,d0
            bra.s    .loop
.done:
            rts
; End of subroutine: strings.copy


; ---- Subroutine: strings.ncopy ----
    ALIGN 2

strings.ncopy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
            tst.b    d2
            beq      .zero
.loop:
            move.b   (a0)+,d1
            move.b   d1,(a1)+
            beq      .done
            addq.l   #1,d0
            subq.b   #1,d2
            bne      .loop
            ; maxlength bytes reached - null-terminate
            clr.b    (a1)
            rts
.zero:
            clr.b    (a1)
.done:
            rts
; End of subroutine: strings.ncopy


